import { useMemo, useState } from 'react'
import { Users, Hash, TrendingUp, MessageCircle, Heart, BookOpen, Calendar, Bot, X } from 'lucide-react'
import { useAppStore } from '../store'
import { recommendCircles, collectUserSkillTags } from '../utils/recommend'
import { useAllSkills } from '../store'
import { SkillStatus } from '../types'
import { aiRecommendCircles, hasAIConfig, AIError, AICircleSuggestion } from '../utils/ai'

type Tab = 'recommend' | 'joined' | 'hot'

export function CirclesPage() {
  const circles = useAppStore((s) => s.circles)
  const joinedCircleIds = useAppStore((s) => s.joinedCircleIds)
  const joinCircle = useAppStore((s) => s.joinCircle)
  const leaveCircle = useAppStore((s) => s.leaveCircle)
  const addCircle = useAppStore((s) => s.addCircle)
  const notes = useAppStore((s) => s.notes)
  const noteLikes = useAppStore((s) => s.noteLikes)
  const gameStats = useAppStore((s) => s.gameStats)
  const recordAIAdoption = useAppStore((s) => s.recordAIAdoption)
  const recordActivity = useAppStore((s) => s.recordActivity)
  const allSkills = useAllSkills()

  const [tab, setTab] = useState<Tab>('recommend')
  const [showAIModal, setShowAIModal] = useState(false)
  const [aiLoading, setAiLoading] = useState(false)
  const [aiError, setAiError] = useState<string | null>(null)
  const [aiCircles, setAiCircles] = useState<AICircleSuggestion[]>([])
  const [aiChecked, setAiChecked] = useState<Record<number, boolean>>({})

  const masteredTags = useMemo(
    () =>
      collectUserSkillTags(
        allSkills.filter((s) => s.status !== SkillStatus.LOCKED)
      ),
    [allSkills]
  )

  const circleRecs = useMemo(
    () => recommendCircles(circles, joinedCircleIds, masteredTags, 3),
    [circles, joinedCircleIds, masteredTags]
  )

  const displayedCircles =
    tab === 'joined'
      ? circles.filter((c) => joinedCircleIds.includes(c.id))
      : tab === 'hot'
      ? [...circles].sort((a, b) => b.memberCount - a.memberCount)
      : circleRecs.map((r) => r.circle)

  const totalLikes = Object.values(noteLikes).reduce((a, b) => a + b, 0)

  /* ============ AI 推荐圈子 ============ */

  const runAICircles = async () => {
    setAiError(null)
    setAiCircles([])
    if (!hasAIConfig()) {
      setAiError('尚未配置 AI 服务：请到「我的 → 设置」填写 API Key（支持 DeepSeek/通义/Kimi/OpenAI 等）')
      return
    }
    setAiLoading(true)
    try {
      const result = await aiRecommendCircles(masteredTags, circles)
      setAiCircles(result)
      setAiChecked(Object.fromEntries(result.map((_, i) => [i, true])))
    } catch (e) {
      setAiError(e instanceof AIError ? e.message : (e as Error).message)
    } finally {
      setAiLoading(false)
    }
  }

  const adoptAICircles = () => {
    const picked = aiCircles.filter((_, i) => aiChecked[i])
    if (picked.length === 0) return
    picked.forEach((c) => {
      addCircle({
        name: c.name,
        description: c.description,
        category: c.category || 'AI 推荐',
        tags: c.tags?.length ? c.tags : [],
        skillTags: c.skillTags?.length ? c.skillTags : [],
        memberCount: 1,
      })
    })
    recordAIAdoption('circle')
    setShowAIModal(false)
    setAiCircles([])
    recordActivity(`采纳了 AI 推荐的 ${picked.length} 个学习圈子`, 'circle')
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-start justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 flex items-center mb-2">
                <Users className="w-8 h-8 mr-3 text-purple-600" />
                学习圈子
              </h1>
              <p className="text-gray-600">找到志同道合的学习伙伴，一起成长进步</p>
            </div>
            <button
              onClick={() => {
                setAiError(null)
                setAiCircles([])
                setShowAIModal(true)
              }}
              className="bg-purple-600 text-white px-4 py-2 rounded-lg hover:bg-purple-700 transition-colors flex items-center space-x-2"
            >
              <Bot className="w-4 h-4" />
              <span>AI 推荐圈子</span>
            </button>
          </div>
        </div>

        {/* Tabs */}
        <div className="mb-6">
          <div className="flex space-x-1">
            <button
              onClick={() => setTab('recommend')}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                tab === 'recommend'
                  ? 'bg-white text-blue-600 border border-blue-200'
                  : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
              }`}
            >
              推荐圈子
            </button>
            <button
              onClick={() => setTab('joined')}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                tab === 'joined'
                  ? 'bg-white text-blue-600 border border-blue-200'
                  : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
              }`}
            >
              我的圈子（{joinedCircleIds.length}）
            </button>
            <button
              onClick={() => setTab('hot')}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                tab === 'hot'
                  ? 'bg-white text-blue-600 border border-blue-200'
                  : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
              }`}
            >
              热门圈子
            </button>
          </div>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-xl p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">已加入圈子</p>
                <p className="text-2xl font-bold text-gray-900">{joinedCircleIds.length}</p>
              </div>
              <Users className="w-8 h-8 text-purple-500" />
            </div>
          </div>
          <div className="bg-white rounded-xl p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">学习笔记</p>
                <p className="text-2xl font-bold text-gray-900">{notes.length}</p>
              </div>
              <BookOpen className="w-8 h-8 text-blue-500" />
            </div>
          </div>
          <div className="bg-white rounded-xl p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">获得点赞</p>
                <p className="text-2xl font-bold text-gray-900">{totalLikes}</p>
              </div>
              <Heart className="w-8 h-8 text-red-500" />
            </div>
          </div>
          <div className="bg-white rounded-xl p-6 shadow-sm">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">连续学习</p>
                <p className="text-2xl font-bold text-gray-900">{gameStats.currentStreak}天</p>
              </div>
              <Calendar className="w-8 h-8 text-green-500" />
            </div>
          </div>
        </div>

        {/* Circle Cards */}
        {displayedCircles.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {displayedCircles.map((circle) => {
              const isJoined = joinedCircleIds.includes(circle.id)
              const rec = circleRecs.find((r) => r.circle.id === circle.id)
              return (
                <div key={circle.id} className="bg-white rounded-xl shadow-sm border hover:shadow-md transition-shadow">
                  <div className="p-6">
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex-1">
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">{circle.name}</h3>
                        <p className="text-gray-600 text-sm mb-3">{circle.description}</p>
                      </div>
                      <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded-full text-xs font-medium whitespace-nowrap ml-2">
                        {circle.category}
                      </span>
                    </div>

                    {/* Tags */}
                    <div className="flex items-center space-x-2 mb-4">
                      <Hash className="w-4 h-4 text-gray-400" />
                      <div className="flex flex-wrap gap-1">
                        {circle.tags.slice(0, 3).map((tag) => (
                          <span key={tag} className="bg-gray-100 text-gray-700 px-2 py-1 rounded text-xs">
                            {tag}
                          </span>
                        ))}
                        {circle.tags.length > 3 && (
                          <span className="text-gray-500 text-xs">+{circle.tags.length - 3}</span>
                        )}
                      </div>
                    </div>

                    {/* Stats */}
                    <div className="flex items-center justify-between text-sm text-gray-600 mb-4">
                      <div className="flex items-center">
                        <Users className="w-4 h-4 mr-1" />
                        <span>{circle.memberCount.toLocaleString()} 成员</span>
                      </div>
                      {rec && rec.matchPercent > 0 && (
                        <span className="text-xs text-green-600 font-medium">
                          与你的技能匹配 {rec.matchPercent}%
                        </span>
                      )}
                    </div>

                    {/* Action Button */}
                    <button
                      onClick={() => (isJoined ? leaveCircle(circle.id) : joinCircle(circle.id))}
                      className={`w-full py-2 rounded-lg font-medium transition-colors ${
                        isJoined
                          ? 'bg-green-100 text-green-700 hover:bg-green-200'
                          : 'bg-blue-600 text-white hover:bg-blue-700'
                      }`}
                    >
                      {isJoined ? '退出圈子' : '加入圈子'}
                    </button>
                  </div>
                </div>
              )
            })}
          </div>
        ) : (
          <div className="text-center py-12 bg-white rounded-xl border">
            <Users className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h3 className="text-lg font-medium text-gray-900 mb-2">
              {tab === 'joined' ? '还没有加入圈子' : '暂无圈子'}
            </h3>
            <p className="text-gray-600 mb-4">去推荐或热门列表看看，找到适合你的学习圈子</p>
            <button
              onClick={() => setTab('recommend')}
              className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700 transition-colors"
            >
              查看推荐
            </button>
          </div>
        )}

        {/* AI Recommendations */}
        {circleRecs.length > 0 && (
          <div className="mt-12">
            <div className="bg-white rounded-xl shadow-sm border p-6">
              <div className="flex items-center mb-6">
                <TrendingUp className="w-6 h-6 text-blue-600 mr-2" />
                <h2 className="text-xl font-semibold text-gray-900">为你推荐（基于你的技能标签）</h2>
                <MessageCircle className="w-4 h-4 text-blue-400 ml-2" />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {circleRecs.map(({ circle, matchPercent, matchedTags }) => (
                  <div key={circle.id} className="p-4 bg-blue-50 rounded-lg">
                    <h3 className="font-semibold text-blue-900 mb-2">{circle.name}</h3>
                    <p className="text-blue-700 text-sm mb-3">
                      你在学 {matchedTags.join('、')}，与这个圈子的方向高度契合
                    </p>
                    <div className="flex items-center justify-between">
                      <span className="text-xs text-blue-600 font-medium">匹配度: {matchPercent}%</span>
                      <button
                        onClick={() => joinCircle(circle.id)}
                        className="text-blue-600 text-sm font-medium hover:text-blue-800"
                      >
                        立即加入
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
      {/* AI Recommend Circles Modal */}
      {showAIModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg w-[32rem] max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold flex items-center">
                <Bot className="w-5 h-5 text-purple-600 mr-2" />
                AI 推荐学习圈子
              </h3>
              <button onClick={() => setShowAIModal(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-5 h-5" />
              </button>
            </div>

            <p className="text-sm text-gray-500 mb-4">
              基于你的技能标签（{masteredTags.slice(0, 8).join('、') || '暂无'}）生成圈子建议，确认后创建并自动加入。
            </p>

            {aiCircles.length === 0 && !aiLoading && !aiError && (
              <button
                onClick={runAICircles}
                className="w-full bg-purple-600 text-white py-2 rounded-lg font-medium hover:bg-purple-700 transition-colors"
              >
                生成圈子推荐
              </button>
            )}

            {aiLoading && (
              <div className="text-center py-10">
                <div className="animate-spin w-8 h-8 border-4 border-purple-500 border-t-transparent rounded-full mx-auto mb-3"></div>
                <p className="text-gray-600 text-sm">AI 正在寻找合适的学习圈子...</p>
              </div>
            )}

            {aiError && (
              <div className="bg-red-50 border border-red-200 rounded-lg p-4 text-sm text-red-700 mb-3">
                <p className="font-medium mb-1">AI 调用失败</p>
                <p>{aiError}</p>
              </div>
            )}

            {aiCircles.length > 0 && (
              <>
                <div className="space-y-3 mb-4">
                  {aiCircles.map((c, i) => (
                    <label key={i} className={`block p-4 rounded-lg border cursor-pointer transition-colors ${aiChecked[i] ? 'bg-purple-50 border-purple-300' : 'bg-gray-50 border-gray-200'}`}>
                      <div className="flex items-start">
                        <input
                          type="checkbox"
                          checked={!!aiChecked[i]}
                          onChange={() => setAiChecked({ ...aiChecked, [i]: !aiChecked[i] })}
                          className="mt-1 mr-3 rounded"
                        />
                        <div className="flex-1">
                          <div className="flex items-center justify-between">
                            <h4 className="font-semibold text-gray-900">{c.name}</h4>
                            <span className="text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full">{c.category || 'AI 推荐'}</span>
                          </div>
                          <p className="text-sm text-gray-600 mb-1">{c.description}</p>
                          <p className="text-xs text-gray-500 mb-1">💡 {c.reason}</p>
                          {c.skillTags?.length > 0 && (
                            <div className="flex flex-wrap gap-1">
                              {c.skillTags.slice(0, 4).map((t) => (
                                <span key={t} className="bg-gray-100 text-gray-600 px-2 py-0.5 rounded text-xs">#{t}</span>
                              ))}
                            </div>
                          )}
                        </div>
                      </div>
                    </label>
                  ))}
                </div>
                <div className="flex space-x-3">
                  <button
                    onClick={adoptAICircles}
                    disabled={!Object.values(aiChecked).some(Boolean)}
                    className="flex-1 bg-purple-600 text-white py-2 rounded-lg font-medium hover:bg-purple-700 transition-colors disabled:opacity-50"
                  >
                    创建并加入（{Object.values(aiChecked).filter(Boolean).length} 个）
                  </button>
                  <button
                    onClick={runAICircles}
                    className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors text-sm"
                  >
                    换一批
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  )
}
